/* Shared, device-local study progress. No claims of faculty approval. */
(() => {
 'use strict';
 const KEY='ljiet-study-v2', esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let state={items:{},reports:[],sessions:[]};try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.items)state={...state,...saved};}catch{}
 const item=key=>state.items[key]||{};
 function notice(text){let n=document.getElementById('study-notice');if(!n){n=document.createElement('div');n.id='study-notice';n.className='study-notice';n.setAttribute('role','status');document.body.append(n);}n.textContent=text;n.hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>n.hidden=true,3500);}
 function save(){try{localStorage.setItem(KEY,JSON.stringify(state));window.dispatchEvent(new Event('study-change'));return true;}catch{notice('Device storage is unavailable. These changes will last only for this visit.');return false;}}
 function set(key,patch){state.items[key]={...item(key),...patch,updated:Date.now()};save();refresh();}
 function html(key){const s=item(key),review=window.STUDY_CATALOGUE?.questions.find(q=>q.key===key)?.facultyReview;return `<div class="study-actions" data-study-key="${esc(key)}"><button type="button" data-study="bookmark" aria-pressed="${!!s.bookmark}">${s.bookmark?'★ Saved':'☆ Save'}</button><label class="study-state">Your progress<select data-study="status" aria-label="Study status"><option value="">Not started</option>${[['done','✓ Done'],['revise','↻ Revise'],['doubt','? Doubt']].map(([v,t])=>`<option value="${v}" ${s.status===v?'selected':''}>${t}</option>`).join('')}</select></label><button type="button" data-study="report">Flag an issue</button><span class="review-state">${review?`<a href="${esc(review.evidenceUrl)}" target="_blank" rel="noopener noreferrer">Faculty reviewed · ${esc(review.name)} · ${esc(review.date)}</a>`:'Faculty review pending'}</span></div>`;}
 function refresh(){document.querySelectorAll('[data-study-key]').forEach(n=>{const s=item(n.dataset.studyKey),b=n.querySelector('[data-study="bookmark"]'),select=n.querySelector('[data-study="status"]');if(b){b.textContent=s.bookmark?'★ Saved':'☆ Save';b.setAttribute('aria-pressed',!!s.bookmark);}if(select)select.value=s.status||'';});}
 function mount(node,key){node.innerHTML=html(key);}
 function close(dialog){if(dialog.close)dialog.close();dialog.remove();}
 function modal(title,body){const d=document.createElement('dialog');d.className='study-dialog';d.innerHTML=`<div class="dialog-top"><h2>${esc(title)}</h2><button type="button" class="dialog-close" aria-label="Close dialog">×</button></div>${body}`;document.body.append(d);d.querySelector('.dialog-close').onclick=()=>close(d);d.addEventListener('cancel',()=>d.remove());d.addEventListener('click',e=>{if(e.target===d)close(d);});if(d.showModal)d.showModal();else d.setAttribute('open','');return d;}
 function report(key){const q=window.STUDY_CATALOGUE?.questions.find(q=>q.key===key);const d=modal('Help improve this solution',`<p>Question ${esc(q?.number||key)} · Faculty review pending</p><form id="issue-form"><label>Issue type<select name="type"><option>Incorrect answer</option><option>Missing step</option><option>Question image</option><option>Other</option></select></label><label>What should we check?<textarea name="detail" rows="4" required minlength="5" maxlength="2000" placeholder="Describe the mistake or missing step."></textarea></label><p class="study-small">Save a private draft on this device, or open GitHub and submit it to the project. Nothing is sent automatically.</p><div class="dialog-buttons"><button type="submit" class="study-primary">Save draft</button><button type="button" id="send-github">Open GitHub issue ↗</button></div><p id="issue-saved" role="status"></p></form>`);
 const f=d.querySelector('form');function data(){return {key,type:f.elements.type.value,detail:f.elements.detail.value.trim(),at:new Date().toISOString()};}f.onsubmit=e=>{e.preventDefault();state.reports.push(data());const ok=save();d.querySelector('#issue-saved').textContent=ok?'Draft saved on this device. It has not been submitted.':'Draft kept for this visit only; device storage is unavailable.';};d.querySelector('#send-github').onclick=()=>{if(!f.reportValidity())return;const v=data(),url=new URL('https://github.com/sp594809-cloud/python-solve/issues/new');url.searchParams.set('title',`${v.type}: ${key}`);url.searchParams.set('body',`Question: ${key}\nPage: ${location.href}\n\n${v.detail}`);window.open(url.href,'_blank','noopener,noreferrer');};}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-study]'),n=b?.closest('[data-study-key]');if(!n)return;const key=n.dataset.studyKey;if(b.dataset.study==='bookmark')set(key,{bookmark:!item(key).bookmark});if(b.dataset.study==='report')report(key);});
 document.addEventListener('change',e=>{if(e.target.dataset.study==='status')set(e.target.closest('[data-study-key]').dataset.studyKey,{status:e.target.value});});
 window.addEventListener('storage',e=>{if(e.key===KEY){try{state={...state,...JSON.parse(e.newValue||'{"items":{}}')};refresh();window.dispatchEvent(new Event('study-change'));}catch{}}});
 window.StudyTools={item,set,html,mount,notice,modal,esc,state:()=>state,saveSession:session=>{state.sessions.unshift(session);state.sessions=state.sessions.slice(0,30);save();}};
})();
